class Library {
  constructor() {
    this.books = {};
    this.members = {};
    this.holds = {};
  }

  addBook(isbn, title, copies) {
    this.books[isbn] = { title, copies, available: copies, onLoan: 0 };
  }

  addMember(memberId, name) {
    this.members[memberId] = { name, loans: [] };
  }

  borrowBook(isbn, memberId) {
    if (!this.books[isbn] || this.books[isbn].available === 0) {
      throw new Error("No copies available");
    }
    this.books[isbn].available--;
    this.books[isbn].onLoan++;
    this.members[memberId].loans.push(isbn);
  }

  returnBook(isbn, memberId) {
    if (!this.books[isbn] || !this.members[memberId].loans.includes(isbn)) {
      throw new Error("Invalid return");
    }
    this.books[isbn].available++;
    this.books[isbn].onLoan--;
    this.members[memberId].loans = this.members[memberId].loans.filter(l => l !== isbn);

    if (this.holds[isbn] && this.holds[isbn].length > 0) {
      const nextMember = this.holds[isbn].shift();
      this.borrowBook(isbn, nextMember);
    }
  }

  placeHold(isbn, memberId) {
    if (this.books[isbn].available > 0) {
      throw new Error("A copy is available");
    }
    if (this.members[memberId].loans.includes(isbn) || this.holds[isbn]?.includes(memberId)) {
      throw new Error("Member already holds or has this book");
    }
    if (!this.holds[isbn]) {
      this.holds[isbn] = [];
    }
    this.holds[isbn].push(memberId);
  }

  holds(isbn) {
    return this.holds[isbn] || [];
  }
}
```

